===BEGIN llm_candidates.jsonl===
{"title":"Verification of Forecasts Expressed in Terms of Probability","doi":"10.1175/1520-0493(1950)078<0001:VOFEIT>2.0.CO;2","authors":["Glenn W. Brier"],"year":1950,"venue":"Monthly Weather Review","abstract":"Foundational paper introducing a proper quadratic score for evaluating probabilistic forecasts, later known as the Brier score; directly relevant to empirical reliability and calibration evaluation."}
{"title":"A Coefficient of Agreement for Nominal Scales","url":"https://doi.org/10.1177/001316446002000104","doi":"10.1177/001316446002000104","authors":["Jacob Cohen"],"year":1960,"venue":"Educational and Psychological Measurement","abstract":"Introduces Cohen's kappa for measuring agreement between two raters while accounting for agreement expected by chance, providing a foundation for annotation-reliability assessment."}
{"title":"On Optimum Recognition Error and Reject Tradeoff","url":"https://doi.org/10.1109/TIT.1970.1054406","doi":"10.1109/TIT.1970.1054406","authors":["C. K. Chow"],"year":1970,"venue":"IEEE Transactions on Information Theory","abstract":"Develops the classical decision-theoretic tradeoff between recognition error and rejection, foundational for selective prediction and abstention under asymmetric costs."}
{"title":"Evaluating Content Selection in Summarization: The Pyramid Method","url":"https://aclanthology.org/N04-1019/","authors":["Ani Nenkova","Rebecca Passonneau"],"year":2004,"venue":"HLT-NAACL 2004","abstract":"Introduces an empirically grounded method for evaluating summary content selection by weighting semantic content units according to how many human reference summaries contain them, yielding an explicit denominator for coverage."}
{"title":"Computing Reliability for Coreference Annotation","url":"https://aclanthology.org/L04-1486/","authors":["Rebecca J. Passonneau"],"year":2004,"venue":"LREC 2004","abstract":"Develops a reliability methodology for structured linguistic annotation where disagreements can be partial and annotation units are not trivially commensurate."}
{"title":"The Pyramid Method: Incorporating human content selection variation in summarization evaluation","url":"https://doi.org/10.1145/1233912.1233913","doi":"10.1145/1233912.1233913","authors":["Ani Nenkova","Rebecca Passonneau","Kathleen McKeown"],"year":2007,"published":"2007-05-01","venue":"ACM Transactions on Speech and Language Processing","abstract":"Extends the Pyramid Method for summary-content evaluation by explicitly representing variation among human summaries and using weighted semantic content units to assess content coverage."}
{"title":"A Tutorial on Conformal Prediction","url":"https://arxiv.org/abs/0706.3188","arxiv_id":"0706.3188","authors":["Glenn Shafer","Vladimir Vovk"],"year":2008,"venue":"Journal of Machine Learning Research","abstract":"Tutorial treatment of conformal prediction and its coverage guarantees under exchangeability assumptions; useful as a foundation for statistically controlled abstention and uncertainty sets."}
{"title":"Formal and functional assessment of the pyramid method for summary content evaluation","url":"https://doi.org/10.1017/S1351324909005051","doi":"10.1017/S1351324909005051","authors":["Rebecca J. Passonneau"],"year":2010,"venue":"Natural Language Engineering","abstract":"Evaluates the reliability and discriminative power of Pyramid annotations across multiple summarization evaluations, including inter-annotator reliability and consistency of system rankings."}
{"title":"PEAK: Pyramid Evaluation via Automated Knowledge Extraction","url":"https://doi.org/10.1609/aaai.v30i1.10336","doi":"10.1609/aaai.v30i1.10336","authors":["Qian Yang","Rebecca Passonneau","Gerard de Melo"],"year":2016,"venue":"AAAI","abstract":"Automates Pyramid-style summary-content evaluation using extracted knowledge representations, retaining the idea of evaluating semantic information units rather than lexical overlap alone."}
{"title":"Runtime Verification of Temporal Properties over Out-of-order Data Streams","url":"https://arxiv.org/abs/1707.05555","arxiv_id":"1707.05555","authors":["David Basin","Felix Klaedtke","Eugen Zălinescu"],"year":2017,"abstract":"Studies verification of temporal properties when observations arrive out of order, providing transferable machinery for reasoning about changing state and late evidence in event streams."}
{"title":"Selective Classification for Deep Neural Networks","url":"https://arxiv.org/abs/1705.08500","arxiv_id":"1705.08500","authors":["Yonatan Geifman","Ran El-Yaniv"],"year":2017,"venue":"NeurIPS","abstract":"Studies selective classification in which a model may reject inputs, emphasizing the risk-coverage tradeoff and methods for attaining a desired error risk at useful coverage."}
{"title":"Know What You Don't Know: Unanswerable Questions for SQuAD","url":"https://arxiv.org/abs/1806.03822","arxiv_id":"1806.03822","authors":["Pranav Rajpurkar","Robin Jia","Percy Liang"],"year":2018,"venue":"ACL","abstract":"Introduces SQuAD 2.0, combining answerable and adversarially written unanswerable questions so systems must determine when the supplied passage does not support an answer and abstain."}
{"title":"FEVER: a large-scale dataset for Fact Extraction and VERification","url":"https://arxiv.org/abs/1803.05355","arxiv_id":"1803.05355","doi":"10.18653/v1/N18-1074","authors":["James Thorne","Andreas Vlachos","Christos Christodoulopoulos","Arpit Mittal"],"year":2018,"venue":"NAACL","abstract":"Introduces claim verification against textual sources with Supported, Refuted, and NotEnoughInfo labels; supporting or refuting judgments also include the source sentences necessary as evidence."}
{"title":"Can You Trust Your Model's Uncertainty? Evaluating Predictive Uncertainty Under Dataset Shift","authors":["Yaniv Ovadia","Emily Fertig","Jie Ren","Zachary Nado","D. Sculley","Sebastian Nowozin","Joshua Dillon","Balaji Lakshminarayanan","Jasper Snoek"],"year":2019,"venue":"NeurIPS","abstract":"Systematically evaluates predictive uncertainty and calibration under dataset shift, showing that uncertainty quality can deteriorate as inputs move away from the training distribution."}
{"title":"SelectiveNet: A Deep Neural Network with an Integrated Reject Option","url":"https://proceedings.mlr.press/v97/geifman19a.html","authors":["Yonatan Geifman","Ran El-Yaniv"],"year":2019,"venue":"ICML","abstract":"Integrates prediction and selection into a single model trained to achieve a target coverage while minimizing selective risk, making coverage an explicit constraint rather than rewarding indiscriminate rejection."}
{"title":"Agreement is overrated: A plea for correlation to assess human evaluation reliability","url":"https://aclanthology.org/W19-8642/","doi":"10.18653/v1/W19-8642","authors":["Jacopo Amidei","Paul Piwek","Alistair Willis"],"year":2019,"venue":"INLG","abstract":"Examines reliability assessment in NLG human evaluation and argues that inter-annotator agreement alone can be misleading; recommends considering agreement together with correlation measures."}
{"title":"Evaluating the Factual Consistency of Abstractive Text Summarization","url":"https://arxiv.org/abs/1910.12840","arxiv_id":"1910.12840","doi":"10.18653/v1/2020.emnlp-main.750","authors":["Wojciech Kryściński","Bryan McCann","Caiming Xiong","Richard Socher"],"year":2020,"venue":"EMNLP","abstract":"Introduces a source-grounded factual-consistency model that jointly predicts consistency and extracts a supporting source span and an inconsistent summary span, enabling localized evidence for factuality judgments."}
{"title":"On Faithfulness and Factuality in Abstractive Summarization","url":"https://aclanthology.org/2020.acl-main.173/","doi":"10.18653/v1/2020.acl-main.173","authors":["Joshua Maynez","Shashi Narayan","Bernd Bohnet","Ryan McDonald"],"year":2020,"venue":"ACL","abstract":"Uses large-scale human evaluation to characterize hallucinations in abstractive summaries and compares automatic measures, finding textual-entailment measures more informative about source faithfulness than standard overlap metrics."}
{"title":"Asking and Answering Questions to Evaluate the Factual Consistency of Summaries","url":"https://arxiv.org/abs/2004.04228","arxiv_id":"2004.04228","authors":["Alex Wang","Kyunghyun Cho","Mike Lewis"],"year":2020,"venue":"ACL","abstract":"Introduces QAGS, which generates questions from a summary and compares answers obtained from the summary and source; disagreement exposes factual inconsistency and gives interpretable question-answer evidence."}
{"title":"Evaluating Factuality in Generation with Dependency-level Entailment","url":"https://arxiv.org/abs/2010.05478","arxiv_id":"2010.05478","doi":"10.18653/v1/2020.findings-emnlp.322","authors":["Tanya Goyal","Greg Durrett"],"year":2020,"venue":"Findings of EMNLP","abstract":"Evaluates factuality at a finer granularity than whole sentences by predicting entailment of dependency-level semantic relations against source documents, helping localize factual errors."}
{"title":"Fact or Fiction: Verifying Scientific Claims","url":"https://arxiv.org/abs/2004.14974","arxiv_id":"2004.14974","doi":"10.18653/v1/2020.emnlp-main.609","authors":["David Wadden","Shanchuan Lin","Kyle Lo","Lucy Lu Wang","Madeleine van Zuylen","Arman Cohan","Hannaneh Hajishirzi"],"year":2020,"venue":"EMNLP","abstract":"Introduces SciFact, where systems retrieve scientific abstracts, determine whether evidence supports or refutes a claim, and identify rationale spans justifying the decision."}
{"title":"Selective Question Answering under Domain Shift","url":"https://arxiv.org/abs/2006.09462","arxiv_id":"2006.09462","doi":"10.18653/v1/2020.acl-main.503","authors":["Amita Kamath","Robin Jia","Percy Liang"],"year":2020,"venue":"ACL","abstract":"Defines selective QA under domain shift, requiring systems to answer as many questions as possible while maintaining a specified accuracy; demonstrates that raw model probabilities are inadequate and evaluates calibrated abstention by coverage."}
{"title":"Factual Consistency Evaluation for Text Summarization via Counterfactual Estimation","url":"https://aclanthology.org/2021.findings-emnlp.10/","doi":"10.18653/v1/2021.findings-emnlp.10","authors":["Yuexiang Xie","Fei Sun","Yang Deng","Yaliang Li","Bolin Ding"],"year":2021,"venue":"Findings of EMNLP","abstract":"Proposes source-grounded factual-consistency evaluation based on counterfactual estimation, targeting whether information in a generated summary is supported by its source."}
{"title":"The Art of Abstention: Selective Prediction and Error Regularization for Natural Language Processing","url":"https://aclanthology.org/2021.acl-long.84/","doi":"10.18653/v1/2021.acl-long.84","authors":["Ji Xin","Raphael Tang","Yaoliang Yu","Jimmy Lin"],"year":2021,"venue":"ACL-IJCNLP","abstract":"Studies selective prediction across NLP tasks and evaluates confidence estimators for abstention, adding error regularization intended to improve separation of correct from incorrect predictions."}
{"title":"QuestEval: Summarization Asks for Fact-based Evaluation","url":"https://arxiv.org/abs/2103.12693","arxiv_id":"2103.12693","doi":"10.18653/v1/2021.emnlp-main.529","authors":["Thomas Scialom","Paul-Alexis Dray","Sylvain Lamprier","Benjamin Piwowarski","Jacopo Staiano","Patrick Gallinari"],"year":2021,"venue":"EMNLP","abstract":"Uses question generation and question answering over source and summary to evaluate whether generated text preserves relevant source information and remains factually consistent."}
{"title":"How Can We Know When Language Models Know? On the Calibration of Language Models for Question Answering","url":"https://doi.org/10.1162/tacl_a_00407","doi":"10.1162/tacl_a_00407","authors":["Zhengbao Jiang","Jun Araki","Haibo Ding","Graham Neubig"],"year":2021,"venue":"Transactions of the Association for Computational Linguistics","abstract":"Studies whether language-model probabilities in question answering correspond to empirical correctness and investigates techniques for improving confidence calibration."}
{"title":"Human evaluation of automatically generated text: Current trends and best practice guidelines","url":"https://doi.org/10.1016/j.csl.2020.101151","doi":"10.1016/j.csl.2020.101151","authors":["Chris van der Lee","Albert Gatt","Emiel van Miltenburg","Emiel Krahmer"],"year":2021,"venue":"Computer Speech & Language","abstract":"Reviews human-evaluation practice in NLG and provides guidelines covering study design, execution, reporting, reliability, and reproducibility."}
{"title":"Classification with Rejection Based on Cost-sensitive Classification","url":"https://arxiv.org/abs/2010.11748","arxiv_id":"2010.11748","authors":["Nontawat Charoenphakdee","Zhenghang Cui","Yivan Zhang","Masashi Sugiyama"],"year":2021,"venue":"ICML","abstract":"Connects classification with rejection to cost-sensitive classification and develops a theoretically justified reject-option method applicable to binary and multiclass settings."}
{"title":"SummEval: Re-evaluating Summarization Evaluation","url":"https://arxiv.org/abs/2007.12626","arxiv_id":"2007.12626","doi":"10.1162/tacl_a_00373","authors":["Alexander R. Fabbri","Wojciech Kryściński","Bryan McCann","Caiming Xiong","Richard Socher","Dragomir Radev"],"year":2021,"venue":"Transactions of the Association for Computational Linguistics","abstract":"Provides a large meta-evaluation of summarization metrics using both expert and crowdsourced human judgments, creating a common testbed for factual consistency and other evaluation dimensions."}
{"title":"SummaC: Re-Visiting NLI-based Models for Inconsistency Detection in Summarization","url":"https://arxiv.org/abs/2111.09525","arxiv_id":"2111.09525","doi":"10.1162/tacl_a_00453","authors":["Philippe Laban","Tobias Schnabel","Paul N. Bennett","Marti A. Hearst"],"year":2022,"venue":"Transactions of the Association for Computational Linguistics","abstract":"Revisits natural-language-inference approaches to detecting whether summaries contain statements unsupported by their source documents and meta-evaluates them across factual-consistency datasets."}
{"title":"QAFactEval: Improved QA-Based Factual Consistency Evaluation for Summarization","url":"https://arxiv.org/abs/2112.08542","arxiv_id":"2112.08542","doi":"10.18653/v1/2022.naacl-main.187","authors":["Alexander R. Fabbri","Chien-Sheng Wu","Wenhao Liu","Caiming Xiong"],"year":2022,"venue":"NAACL","abstract":"Improves question-answering-based factual consistency evaluation by systematically selecting and combining QA components for testing whether summary claims are supported by source documents."}
{"title":"TRUE: Re-evaluating Factual Consistency Evaluation","url":"https://arxiv.org/abs/2204.04991","arxiv_id":"2204.04991","authors":["Or Honovich","Roee Aharoni","Jonathan Herzig","Hagai Taitelbaum","Doron Kukliansy","Vered Cohen","Thomas Scialom","Idan Szpektor","Avinatan Hassidim","Yossi Matias"],"year":2022,"abstract":"Constructs a standardized collection of factual-consistency datasets and performs an example-level meta-evaluation of metrics across summarization, dialogue, paraphrasing, and fact verification."}
{"title":"Attributed Question Answering: Evaluation and Modeling for Attributed Large Language Models","url":"https://arxiv.org/abs/2212.08037","arxiv_id":"2212.08037","authors":["Bernd Bohnet","Vinh Q. Tran","Pat Verga","Roee Aharoni","Daniel Andor","Livio Baldini Soares","Massimiliano Ciaramita","Jacob Eisenstein","Kuzman Ganchev","Jonathan Herzig","Kai Hui","Tom Kwiatkowski","Ji Ma","Jianmo Ni","Lierni Sestorain Saralegui","Tal Schuster","William W. Cohen","Michael Collins","Dipanjan Das","Donald Metzler","Slav Petrov","Kellie Webster"],"year":2022,"abstract":"Defines attributed question answering, where answers must be accompanied by evidence sources that support them, and develops human and automatic evaluation of answer quality and attribution."}
{"title":"FActScore: Fine-grained Atomic Evaluation of Factual Precision in Long Form Text Generation","url":"https://arxiv.org/abs/2305.14251","arxiv_id":"2305.14251","doi":"10.18653/v1/2023.emnlp-main.741","authors":["Sewon Min","Kalpesh Krishna","Xinxi Lyu","Mike Lewis","Wen-tau Yih","Pang Wei Koh","Mohit Iyyer","Luke Zettlemoyer","Hannaneh Hajishirzi"],"year":2023,"venue":"EMNLP","abstract":"Decomposes long-form generations into atomic facts and measures factual precision as the proportion of atomic claims supported by a designated knowledge source, enabling claim-level verification."}
{"title":"AlignScore: Evaluating Factual Consistency with A Unified Alignment Function","url":"https://arxiv.org/abs/2305.16739","arxiv_id":"2305.16739","doi":"10.18653/v1/2023.acl-long.634","authors":["Yuheng Zha","Yichi Yang","Ruichen Li","Zhiting Hu"],"year":2023,"venue":"ACL","abstract":"Learns a unified text-alignment function for source-grounded factual-consistency evaluation and evaluates it across multiple factuality and information-alignment tasks."}
{"title":"Revisiting the Gold Standard: Grounding Summarization Evaluation with Robust Human Evaluation","url":"https://aclanthology.org/2023.acl-long.228/","doi":"10.18653/v1/2023.acl-long.228","authors":["Yixin Liu","Alex Fabbri","Pengfei Liu","Yilun Zhao","Linyong Nan","Ruilin Han","Simeng Han","Shafiq Joty","Chien-Sheng Wu","Caiming Xiong","Dragomir Radev"],"year":2023,"venue":"ACL","abstract":"Introduces robust human evaluation based on Atomic Content Units and the RoSE benchmark, explicitly measuring semantic content coverage with fine-grained units and reporting annotator reliability."}
{"title":"Enabling Large Language Models to Generate Text with Citations","url":"https://arxiv.org/abs/2305.14627","arxiv_id":"2305.14627","doi":"10.18653/v1/2023.emnlp-main.398","authors":["Tianyu Gao","Howard Yen","Jiatong Yu","Danqi Chen"],"year":2023,"venue":"EMNLP","abstract":"Introduces ALCE for long-form generation with citations and evaluates citation quality, including whether cited passages entail generated claims and whether claims that require support are adequately cited."}
{"title":"RAGAS: Automated Evaluation of Retrieval Augmented Generation","url":"https://arxiv.org/abs/2309.15217","arxiv_id":"2309.15217","doi":"10.18653/v1/2024.eacl-demo.16","authors":["Shahul Es","Jithin James","Luis Espinosa-Anke","Steven Schockaert"],"year":2024,"venue":"EACL System Demonstrations","abstract":"Introduces a reference-free evaluation framework for RAG pipelines with separate dimensions for retrieval relevance, use of retrieved context, and faithfulness of generated answers to that context."}
{"title":"Conformal Risk Control","url":"https://arxiv.org/abs/2208.02814","arxiv_id":"2208.02814","authors":["Anastasios N. Angelopoulos","Stephen Bates","Adam Fisch","Lihua Lei","Tal Schuster"],"year":2024,"venue":"ICLR","abstract":"Extends conformal methodology from set coverage to controlling expected values of general monotone loss functions, with applications including language and question-answering losses."}
{"title":"ACUEval: Fine-grained Hallucination Evaluation and Correction for Abstractive Summarization","url":"https://aclanthology.org/2024.findings-acl.597/","doi":"10.18653/v1/2024.findings-acl.597","authors":["David Wan","Koustuv Sinha","Srini Iyer","Asli Celikyilmaz","Mohit Bansal","Ramakanth Pasunuru"],"year":2024,"venue":"Findings of ACL","abstract":"Decomposes summaries into atomic content units and checks individual units against source text, enabling fine-grained hallucination detection rather than a single whole-summary faithfulness score."}
{"title":"On the Role of Summary Content Units in Text Summarization Evaluation","url":"https://arxiv.org/abs/2404.01701","arxiv_id":"2404.01701","doi":"10.18653/v1/2024.naacl-short.25","authors":["Marcel Nawrath","Agnieszka Nowak","Tristan Ratz","Danilo C. Walenta","Juri Opitz","Leonardo F. R. Ribeiro","João Sedoc","Daniel Deutsch","Simon Mille","Yixin Liu","Lining Zhang","Sebastian Gehrmann","Saad Mahamood","Miruna Clinciu","Khyathi Chandu","Yufang Hou"],"year":2024,"venue":"NAACL","abstract":"Studies semantic summary-content units as the basic objects of evaluation and compares different unit definitions and annotation approaches for content-oriented summarization assessment."}
{"title":"On the Capacity of Citation Generation by Large Language Models","url":"https://arxiv.org/abs/2410.11217","arxiv_id":"2410.11217","authors":["Haosheng Qian","Yixing Fan","Ruqing Zhang","Jiafeng Guo"],"year":2024,"abstract":"Investigates LLM citation-generation capability and evaluates generated citations for qualities beyond mere citation presence, including their relationship to the claims they are intended to support."}
{"title":"Learning Fine-Grained Grounded Citations for Attributed Large Language Models","url":"https://arxiv.org/abs/2408.04568","arxiv_id":"2408.04568","authors":["Lei Huang","Xiaocheng Feng","Weitao Ma","Yuxuan Gu","Weihong Zhong","Xiachong Feng","Weijiang Yu","Weihua Peng","Duyu Tang","Dandan Tu","Bing Qin"],"year":2024,"abstract":"Studies fine-grained citations for attributed generation, aiming to connect generated claims to localized supporting evidence rather than attaching only coarse document-level references."}
{"title":"Model Internals-based Answer Attribution for Trustworthy Retrieval-Augmented Generation","url":"https://arxiv.org/abs/2406.13663","arxiv_id":"2406.13663","authors":["Jirui Qi","Gabriele Sarti","Raquel Fernández","Arianna Bisazza"],"year":2024,"abstract":"Introduces an attribution approach for RAG that links answer content to retrieved documents using model internals and evaluates its agreement with human evidence-attribution judgments."}
{"title":"Conformal Prediction for Natural Language Processing: A Survey","url":"https://arxiv.org/abs/2405.01976","arxiv_id":"2405.01976","doi":"10.1162/tacl_a_00715","authors":["Margarida M. Campos","António Farinhas","Chrysoula Zerva","Mário A. T. Figueiredo","André F. T. Martins"],"year":2024,"venue":"Transactions of the Association for Computational Linguistics","abstract":"Surveys conformal prediction in NLP, including assumptions, prediction sets, risk control, structured language outputs, and complications that arise when applying statistical coverage guarantees to language tasks."}
{"title":"Better than Random: Reliable NLG Human Evaluation with Constrained Active Sampling","url":"https://arxiv.org/abs/2406.07967","arxiv_id":"2406.07967","doi":"10.1609/aaai.v38i17.29857","authors":["Jie Ruan","Xiao Pu","Mingqi Gao","Xiaojun Wan","Yuesheng Zhu"],"year":2024,"published":"2024-03-24","venue":"AAAI","abstract":"Studies sampling reliability in NLG human evaluation and proposes constrained active sampling to make limited human-review budgets more representative and stable across system comparisons."}
{"title":"Defining and Detecting Vulnerability in Human Evaluation Guidelines: A Preliminary Study Towards Reliable NLG Evaluation","url":"https://aclanthology.org/2024.naacl-long.441/","doi":"10.18653/v1/2024.naacl-long.441","authors":["Jie Ruan","Wenqing Wang","Xiaojun Wan"],"year":2024,"venue":"NAACL","abstract":"Investigates how weaknesses or ambiguity in human-evaluation instructions can compromise NLG judgments and develops methodology for identifying evaluation-guideline vulnerabilities."}
{"title":"ReproHum #0892-01: The painful route to consistent results: A reproduction study of human evaluation in NLG","url":"https://aclanthology.org/2024.humeval-1.24/","authors":["Irene Mondella","Huiyuan Lai","Malvina Nissim"],"year":2024,"venue":"HumEval","abstract":"Reproduces an NLG human-evaluation study and analyzes difficulties in obtaining consistent judgments, providing empirical evidence about protocol sensitivity and evaluation reliability."}
{"title":"Factual consistency evaluation of summarization in the Era of large language models","url":"https://doi.org/10.1016/j.eswa.2024.124456","doi":"10.1016/j.eswa.2024.124456","authors":["Zheheng Luo","Qianqian Xie","Sophia Ananiadou"],"year":2024,"published":"2024-11-15","venue":"Expert Systems with Applications","abstract":"Evaluates source-grounded factual consistency of summaries in the LLM era and studies metric behavior against human factuality judgments, including a clinical summarization setting."}
{"title":"Correctness is not Faithfulness in RAG Attributions","url":"https://arxiv.org/abs/2412.18004","arxiv_id":"2412.18004","authors":["Jonas Wallat","Maria Heuss","Maarten de Rijke","Avishek Anand"],"year":2024,"abstract":"Separates attribution correctness from attribution faithfulness in RAG, showing that a citation can support an answer while failing to reflect the evidence that actually influenced generation."}
{"title":"ChronoFact: Timeline-based Temporal Fact Verification","url":"https://arxiv.org/abs/2410.14964","arxiv_id":"2410.14964","doi":"10.24963/ijcai.2025/893","authors":["Anab Maulana Barik","Wynne Hsu","Mong Li Lee"],"year":2025,"venue":"IJCAI","abstract":"Frames temporal fact verification around timelines so claims can be evaluated against evidence valid at relevant times, rather than treating factual truth as temporally invariant."}
{"title":"SelfCite: Self-Supervised Alignment for Context Attribution in Large Language Models","url":"https://arxiv.org/abs/2502.09604","arxiv_id":"2502.09604","authors":["Yung-Sung Chuang","Benjamin Cohen-Wang","Shannon Zejiang Shen","Zhaofeng Wu","Hu Xu","Xi Victoria Lin","James R. Glass","Shang-Wen Li","Wen-Tau Yih"],"year":2025,"venue":"ICML","abstract":"Uses context ablations to derive self-supervised citation rewards related to citation necessity and sufficiency, then aligns models to produce better-supported context attributions."}
{"title":"Do LLMs Know When to NOT Answer? Investigating Abstention Abilities of Large Language Models","url":"https://arxiv.org/abs/2407.16221","arxiv_id":"2407.16221","authors":["Nishanth Madhusudhan","Sathwik Tejaswi Madhusudhan","Vikas Yadav","Masoud Hashemi"],"year":2025,"venue":"COLING","abstract":"Systematically evaluates LLM abstention across question-answering settings and introduces abstention-focused evaluation rather than crediting models merely for answering more questions."}
{"title":"When Benchmarks Age: Temporal Misalignment through Large Language Model Factuality Evaluation","url":"https://arxiv.org/abs/2510.07238","arxiv_id":"2510.07238","doi":"10.18653/v1/2026.eacl-short.37","authors":["Xunyi Jiang","Dingyi Chang","Julian McAuley","Xin Xu"],"year":2026,"venue":"EACL","abstract":"Examines temporal misalignment in factuality benchmarks, showing why factuality evaluation must account for benchmark age and whether facts and evidence remain current at evaluation time."}
{"title":"Cited but Not Verified: Parsing and Evaluating Source Attribution in LLM Deep Research Agents","url":"https://arxiv.org/abs/2605.06635","arxiv_id":"2605.06635","authors":["Hailey Onweller","Elias Lumer","Austin Huber","Pia Ramchandani","Vamse Kumar Subbiah","Corey Feld"],"year":2026,"published":"2026-05-07","abstract":"Evaluates source attribution in deep-research outputs by checking whether cited sources work, contain relevant material, and actually substantiate generated factual claims rather than merely appearing plausible."}
{"title":"Do You Need a Frontier Model as a Citation Verifier? Benchmarking Rubric LLMs for Deep-Research Source Attribution","url":"https://arxiv.org/abs/2607.08700","arxiv_id":"2607.08700","authors":["Ethan Leung","Elias Lumer","Corey Feld","Austin Huber","Vamse Kumar Subbiah","Kevin Paul"],"year":2026,"published":"2026-07-09","abstract":"Benchmarks LLM citation verifiers against human-reviewed and adjudicated judgments of source relevance and factual support, emphasizing false-positive and false-negative behavior rather than raw judge agreement alone."}
{"title":"Do LLMs Know When Evidence is Insufficient? An Evidence Sufficiency Benchmark for Answer-Abstention Calibration in Retrieval-Augmented Generation","url":"https://doi.org/10.32604/cmc.2026.086343","doi":"10.32604/cmc.2026.086343","authors":["Hantian Zhang","Wentai Wu"],"year":2026,"published":"2026-08-13","venue":"Computers, Materials & Continua","abstract":"Benchmarks answer-versus-abstain behavior under full, partial, irrelevant, absent, and conflicting retrieved evidence, directly testing whether RAG systems distinguish insufficient evidence from supported answerability."}
{"title":"Agreement Metrics for LLM-as-Judge Evaluation: What to Report and Why","url":"https://arxiv.org/abs/2606.00093","arxiv_id":"2606.00093","authors":["Delip Rao","Chris Callison-Burch"],"year":2026,"published":"2026-05-25","abstract":"Analyzes agreement metrics for LLM-as-judge evaluation and discusses what different measures reveal, including treatment of judge abstentions and the need to report coverage alongside agreement."}
{"title":"Augmenting Human Evaluation with LLM Judges: How Many Human Reviews Do You Need?","url":"https://arxiv.org/abs/2605.16354","arxiv_id":"2605.16354","authors":["Jane Paik Kim"],"year":2026,"published":"2026-05-08","abstract":"Studies hybrid evaluation designs that combine LLM judges with retained human review, focusing on how much human validation is needed rather than treating model judgments as an unvalidated gold standard."}
===END llm_candidates.jsonl===
